package edu.pbs.hub.config; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.HttpStatus; import org.springframework.web.server.ResponseStatusException;
@Component public class AdminGuard { @Value("${app.admin-key}") private String adminKey; public void check(HttpServletRequest req){String supplied=req.getHeader("X-ADMIN-KEY"); if(adminKey==null||adminKey.equals("change-this-admin-key")||!adminKey.equals(supplied)) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Admin key missing or invalid. Configure ADMIN_KEY on backend.");} }
